package com.example.onboarding_tracker;

import java.util.Date;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;

/**
 * id number Generated by the database. The client never sends it.
 * name text Required, not blank.
 * role text Required, not blank.
 * onboardingDate date Required. Format yyyy-MM-dd, for example 2026-11-10.
 * 
 * Employee
 */
@Entity
public class Employee {

	@Id
	@GeneratedValue(strategy = GenerationType.AUTO)
	private Long id;

	@NotBlank
	String name;

	@NotBlank
	String role;

	@Valid
	Date onboardingDate;

	public Long getId() {
		return id;
	}

	public void setId(Long id) {
		this.id = id;
	}

	public String getName() {
		return name;
	}

	public void setName(String name) {
		this.name = name;
	}

	public String getRole() {
		return role;
	}

	public void setRole(String role) {
		this.role = role;
	}

	public Date getOnboardingDate() {
		return onboardingDate;
	}

	public void seOnboardingDate(Date onboardingDate) {
		this.onboardingDate = onboardingDate;
	}

}
